import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;
import org.json.*;

public class ReportServlet extends HttpServlet {
    private static final Logger logger = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String startDate = req.getParameter("start");
        String endDate = req.getParameter("end");
        String sortCol = req.getParameter("sort");
        String userId = (String) req.getSession().getAttribute("user_id");

        if (userId == null) {
            resp.sendError(401, "Not authenticated");
            return;
        }

        if (reportType == null || startDate == null || endDate == null) {
            resp.sendError(400, "Missing required parameters");
            return;
        }

        // Validate report type against allowed values
        if (!reportType.matches("^(sales|inventory|returns)$")) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Build query - sort column is user-controlled
        String baseQuery = "SELECT item_id, item_name, quantity, total_price, txn_date " +
                          "FROM " + reportType + "_reports " +
                          "WHERE org_id = (SELECT org_id FROM users WHERE user_id = ?) " +
                          "AND txn_date BETWEEN ? AND ?";

        // Sort column injection point - developer assumed frontend dropdown
        if (sortCol != null && !sortCol.isEmpty()) {
            baseQuery += " ORDER BY " + sortCol;
        }

        logger.info("Report query for user " + userId + ": type=" + reportType);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement stmt = conn.prepareStatement(baseQuery)) {

            stmt.setString(1, userId);
            stmt.setString(2, startDate);
            stmt.setString(3, endDate);

            ResultSet rs = stmt.executeQuery();
            JSONArray results = new JSONArray();

            while (rs.next()) {
                JSONObject row = new JSONObject();
                row.put("item_id", rs.getString("item_id"));
                row.put("item_name", rs.getString("item_name"));
                row.put("quantity", rs.getInt("quantity"));
                row.put("total_price", rs.getDouble("total_price"));
                row.put("txn_date", rs.getString("txn_date"));
                results.put(row);
            }

            resp.setContentType("application/json");
            resp.getWriter().write(results.toString());

        } catch (SQLException e) {
            logger.warning("SQL error: " + e.getMessage());
            resp.sendError(500, "Report generation failed: " + e.getSQLState());
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // Export endpoint - reuses same logic
        doGet(req, resp);
    }
}
